function UIActivityPtMainNode:OnBtnDesc()
    CfUtils.ShowModuleToast(ActivityPtComponent:GetActivityConf().ruleId)
end


function UIActivityPtMainNode:OnBtnGo()
    local isUnlock = ActivityPtUtils.IsUnlockQuest(self._curSelectId)
    local ActivityPtComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityPtComponent)
    local num = ActivityPtComponent:GetGetActivityGoodsNum()
    local vo = ActivityPtUtils.GetActivityPtPlotVo(self._curSelectId)
    local needNum = vo.unlockPropNum
    local isEnough = false
    if checkNumber(num) >= checkNumber(vo.unlockPropNum) then
        isEnough = true 
    end
    -- 未解锁点数充足
    if (not isUnlock) and isEnough then
        GameUtils.Toast(localize('请先完成前一话'))
        return
    -- 未解锁点数不足    
    elseif  (not isUnlock)  then
        GameUtils.Toast(localize('活动点数不足'))
        return
    end
    self:PlayPlot(vo, function()
        local isPass = ActivityPtUtils.IsPassQuest(self._curSelectId)
        if not isPass then 
            ActivityPtComponent:OverseaActivityPtQuestPlotReq(self._curUuid, vo.id, function(rewards)
                UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards } })
                self:FillPlots()
            end)
        end
    end)
end

---播放剧情
function UIActivityPtMainNode:PlayPlot(vo, endCb)
    if not vo then
        return
    end
    if self._isPlayPlot then
        return
    end
    self._isPlayPlot = true
    local plotIds = CfUtils.Split(vo.storyId)
    if not plotIds then
        GameUtils.Toast(localize("该关卡没有剧情参数"))
        self._isPlayPlot = false
        return
    end
    
    self._curPlotIndex = 1
    self:PlayingPlot(plotIds, vo, endCb)
end

---剧情播放中
function UIActivityPtMainNode:PlayingPlot(plotIds, vo, endCb)
    ChapterUtils.ProcessChapter(checkNumber(plotIds[self._curPlotIndex]), function(go)
        self._plotGo = go
    end, function()
        if isNotNull(self._plotGo) then
            KTool.SafeDelete(self._plotGo)
            self._plotGo = nil
        end
        if self._curPlotIndex >= table.count(plotIds) then
            -- GameUtils.PlayMainBGM()    
            if endCb then
                local t = ActivityPtComponent:GetActivityConf()
                if isNotNull(t.bgm) then
                    local CriWareUtils = import('Game.Entry.CriWareUtilsFix')
                    CriWareUtils.PlayMusicById(t.bgm)
                end
                endCb()
            end
            self._isPlayPlot = false
        else
            self._curPlotIndex = self._curPlotIndex + 1
            self:PlayingPlot(plotIds , vo ,endCb)
        end
    end)
end

function UIActivityPtMainNode:OnDestroy()
    GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.MainActivityPTTask)
    GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.MainActivityPTStory)
    CfUtils.SetTopCommonCb(nil)
    if self._co ~= nil then
        cs_coroutine.stop(self._co)
        self._co = nil
    end
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIActivityPtMainNode
